    (function() {
      function containsPoint(el, e) {
        if (!el || !el.getBoundingClientRect) return false;
        var r = el.getBoundingClientRect();
        return e.clientX >= r.left && e.clientX <= r.right && e.clientY >= r.top && e.clientY <= r.bottom;
      }

      function findEditableImage(target, event) {
        if (!target) return null;
        var img = target.closest && target.closest('img[data-hi-edit-image], [data-hi-edit-image]');
        if (img && containsPoint(img, event)) return img;

        var stack = document.elementsFromPoint ? document.elementsFromPoint(event.clientX, event.clientY) : [];
        for (var i = 0; i < stack.length; i++) {
          var el = stack[i];
          if (el.matches && el.matches('img[data-hi-edit-image], [data-hi-edit-image]') && containsPoint(el, event)) return el;
        }
        return null;
      }

      function getImageIndex(img) {
        var attr = img && img.getAttribute && img.getAttribute('data-hi-edit-image');
        if (attr !== null && attr !== undefined && attr !== '') return Number(attr);
        return Array.prototype.indexOf.call(document.querySelectorAll('img'), img);
      }

      document.addEventListener('click', function(event) {
        // ── ALWAYS block navigation for any click inside the editor ──
        var anyLink = event.target.closest && event.target.closest('a[href]');
        if (anyLink) event.preventDefault();

        // ── 1. Link — check FIRST so children inside <a> are handled correctly ──
        //    (children have pointer-events:none so event.target IS the <a> itself)
        var linkTarget = event.target.closest && event.target.closest('a[data-hi-edit-link]');
        if (linkTarget) {
          event.stopPropagation();
          var rect = linkTarget.getBoundingClientRect();
          var rawHref = linkTarget.getAttribute('href') || '';
          var rawTarget = linkTarget.getAttribute('target') || '';
          var rawRel = linkTarget.getAttribute('rel') || '';
          window.parent.postMessage({
            source: 'homepage-editultimate',
            type: 'link-click',
            index: Number(linkTarget.getAttribute('data-hi-edit-link')),
            value: rawHref,
            target: rawTarget,
            rel: rawRel,
            textContent: (linkTarget.textContent || '').trim(),
            rect: { top: rect.top, left: rect.left, width: rect.width, height: rect.height }
          }, '*');
          return;
        }

        // ── 2. Text node ──
        var textTarget = event.target.closest && event.target.closest('[data-hi-edit-text]');
        if (textTarget) {
          event.stopPropagation();
          return;
        }

        // ── 3. Image ──
        var imageTarget = findEditableImage(event.target, event);
        if (imageTarget) {
          event.preventDefault();
          event.stopPropagation();
          if (event.stopImmediatePropagation) event.stopImmediatePropagation();
          var rect = imageTarget.getBoundingClientRect();
          window.parent.postMessage({
            source: 'homepage-editultimate',
            type: 'image',
            index: getImageIndex(imageTarget),
            value: imageTarget.getAttribute('src') || '',
            rect: { top: rect.top, left: rect.left, width: rect.width, height: rect.height }
          }, '*');
          return;
        }

      }, true);

      document.addEventListener('dragstart', function(event) {
        if (findEditableImage(event.target, event)) event.preventDefault();
      }, true);

      document.addEventListener('blur', function(event) {
        var target = event.target.closest && event.target.closest('[data-hi-edit-text]');
        if (!target) return;
        window.parent.postMessage({
          source: 'homepage-editultimate',
          type: 'text-update',
          index: Number(target.getAttribute('data-hi-edit-text')),
          value: target.textContent || ''
        }, '*');
      }, true);

      // ── Listen for patch commands from parent (no reload needed) ──────────
      window.addEventListener('message', function(event) {
        var data = event.data;
        if (!data || data.source !== 'homepage-editultimate-patch') return;

        if (data.type === 'patch-link') {
          var link = document.querySelector('a[data-hi-edit-link="' + data.index + '"]');
          if (link) {
            link.setAttribute('href', data.href);
            if (data.target) link.setAttribute('target', data.target); else link.removeAttribute('target');
            if (data.rel) link.setAttribute('rel', data.rel); else link.removeAttribute('rel');
            if (data.text != null && data.text !== "") link.textContent = data.text;
          }
          return;
        }

        if (data.type === 'patch-image') {
          var imgs = document.querySelectorAll('[data-hi-edit-image="' + data.index + '"]');
          imgs.forEach(function(img) { img.setAttribute('src', data.src); });
          return;
        }

        if (data.type === 'patch-text') {
          var span = document.querySelector('[data-hi-edit-text="' + data.index + '"]');
          if (span && span.textContent !== data.value) span.textContent = data.value;
          return;
        }
      });

      // ── Block ALL navigation attempts inside the iframe ──────────────────
      // 1. Intercept <form> submissions
      document.addEventListener('submit', function(event) {
        event.preventDefault();
        event.stopPropagation();
      }, true);

      // 2. Override window.open so popups don't escape
      window.open = function() { return null; };

      // 3. Block any attempt to set location (catches JS-driven navigation)
      try {
        Object.defineProperty(window, 'location', {
          get: function() { return window._hi_safe_location || location; },
          set: function() { /* noop – block assignment */ },
          configurable: false
        });
      } catch(e) { /* some browsers won't allow redefining location – that's fine */ }

      // 4. Intercept beforeunload / unload as a last resort signal
      window.addEventListener('beforeunload', function(event) {
        event.preventDefault();
        event.returnValue = '';
        window.parent.postMessage({ source: 'homepage-editultimate', type: 'navigation-blocked' }, '*');
      });
    })();
